function initTabNavigation(){const n=document.querySelectorAll(".sn-tab-btn"),e=document.querySelectorAll(".sn-section");function t(t){n.forEach(n=>{const e=n.dataset.tab===t;n.classList.toggle("active",e),n.setAttribute("aria-selected",e?"true":"false")}),e.forEach(n=>{const e=n.id===t;n.classList.toggle("active",e)}),history.pushState?history.pushState(null,null,`#${t}`):location.hash=`#${t}`}n.forEach(n=>{n.addEventListener("click",()=>{t(n.dataset.tab)})});const i=window.location.hash.replace("#","");i&&document.getElementById(i)&&t(i)}function renderBiography(){const n=document.getElementById("bio-content");if(!n||"undefined"==typeof SANYAL_DATA)return;const{biography:e}=SANYAL_DATA;n.innerHTML=`\n        <div class="bio-layout">\n            <div class="bio-main-card">\n                <h3>🚩 Architect of Revolutionary Nationalism</h3>\n                <p class="bio-prose">${e.summary}</p>\n                \n                <div class="bio-key-aspects">\n                    <div class="bio-aspect-card">\n                        <h4><span>📜</span> Ideological Foundation</h4>\n                        <p style="margin:0; font-size: 0.95rem; color: var(--sn-text-muted);">\n                            Bridged 19th-century Swadeshi thought and 20th-century armed revolution. Formulated the HRA's vision of democratic federalism and anti-exploitation.\n                        </p>\n                    </div>\n                    <div class="bio-aspect-card">\n                        <h4><span>🤝</span> Mentor to Legendary Martyrs</h4>\n                        <p style="margin:0; font-size: 0.95rem; color: var(--sn-text-muted);">\n                            Directly inspired and recruited Bhagat Singh, Chandrashekhar Azad, Ram Prasad Bismil, Ashfaqulla Khan, and Jatin Das.\n                        </p>\n                    </div>\n                </div>\n            </div>\n\n            <div class="bio-side-panel">\n                <div class="info-box-widget">\n                    <h4>Biographical Details</h4>\n                    <ul class="info-box-list">\n                        <li><span class="info-box-label">Born:</span> <span class="info-box-val">${e.birthDate}</span></li>\n                        <li><span class="info-box-label">Birthplace:</span> <span class="info-box-val">Varanasi, UP</span></li>\n                        <li><span class="info-box-label">Died:</span> <span class="info-box-val">${e.deathDate}</span></li>\n                        <li><span class="info-box-label">Key Org:</span> <span class="info-box-val">HRA Co-Founder</span></li>\n                        <li><span class="info-box-label">Exile:</span> <span class="info-box-val">Cellular Jail (Twice)</span></li>\n                    </ul>\n                </div>\n\n                <div class="audio-card">\n                    <h4>🎧 Audio Guide Simulation</h4>\n                    <p>Listen to a narration detailing Sachindra Nath Sanyal's life and the founding of HRA.</p>\n                    <button id="btn-audio-play" class="btn-audio-play">\n                        <span>▶️</span> Play Narration\n                    </button>\n                </div>\n            </div>\n        </div>\n    `}function initAudioGuide(){document.addEventListener("click",n=>{if(n.target&&("btn-audio-play"===n.target.id||n.target.closest("#btn-audio-play"))){const n=document.getElementById("btn-audio-play");if("speechSynthesis"in window)if(window.speechSynthesis.speaking)window.speechSynthesis.cancel(),n.innerHTML="<span>▶️</span> Play Narration";else{const e=new SpeechSynthesisUtterance("Sachindra Nath Sanyal was a foundational ideologue of the Indian revolutionary movement. Born in Varanasi in 1893, he co-founded the Hindustan Republican Association in Kanpur in 1924. Author of Bandi Jeevan, the sacred text of Indian revolutionaries, Sanyal mentored iconic martyrs such as Bhagat Singh and Chandrashekhar Azad, enduring exile to the Cellular Jail twice during his lifelong battle for freedom.");e.rate=.95,e.onend=()=>{n.innerHTML="<span>▶️</span> Play Narration"},window.speechSynthesis.speak(e),n.innerHTML="<span>⏹️</span> Stop Narration"}else alert("Audio Speech Synthesis is not supported in this browser.")}})}function renderTimeline(){const n=document.getElementById("timeline-content");n&&"undefined"!=typeof SANYAL_DATA&&(n.innerHTML=`\n        <div class="timeline-container">\n            ${SANYAL_DATA.timeline.map(n=>`\n                <div class="timeline-card">\n                    <div class="timeline-dot"></div>\n                    <span class="timeline-year-badge">${n.year}</span>\n                    <h3 class="timeline-card-title">${n.title}</h3>\n                    <div class="timeline-card-cat">${n.category}</div>\n                    <p class="timeline-card-desc">${n.description}</p>\n                </div>\n            `).join("")}\n        </div>\n    `)}function renderHRAHistory(){const n=document.getElementById("hra-content");if(!n||"undefined"==typeof SANYAL_DATA)return;const{hraHistory:e}=SANYAL_DATA;n.innerHTML=`\n        <div class="bio-main-card">\n            <h3 style="margin-top:0;">🚩 ${e.title}</h3>\n            <p class="bio-prose" style="margin-bottom: 1.5rem;">\n                Founded in <strong>${e.foundingLocation}</strong> in <strong>${e.foundingDate}</strong> by \n                <strong>${e.founders.join(", ")}</strong>, the HRA represented a revolutionary shift from regional secret societies to an organized pan-Northern movement.\n            </p>\n            <div style="background: rgba(255, 153, 51, 0.1); border-left: 4px solid var(--sn-saffron); padding: 1rem 1.25rem; border-radius: 0 var(--sn-radius) var(--sn-radius) 0; font-size: 1.05rem; margin-bottom: 2rem;">\n                🎯 <strong>Core Objective:</strong> ${e.coreObjective}\n            </div>\n\n            <h4 style="font-family: var(--sn-font-heading); font-size: 1.4rem; color: var(--sn-saffron); margin-bottom: 1rem;">Four Foundational Pillars of HRA</h4>\n            <div class="hra-grid">\n                ${e.pillars.map(n=>`\n                    <div class="hra-pillar-card">\n                        <div class="hra-pillar-icon">${n.icon}</div>\n                        <h4 class="hra-pillar-title">${n.title}</h4>\n                        <p class="hra-pillar-desc">${n.description}</p>\n                    </div>\n                `).join("")}\n            </div>\n\n            <div class="hsra-box">\n                <h3>🔥 Transformation into HSRA (1928)</h3>\n                <p style="margin:0; font-size: 1rem; color: var(--sn-text-main); line-height: 1.7;">\n                    ${e.evolutionToHSRA}\n                </p>\n            </div>\n        </div>\n    `}function renderWritings(){const n=document.getElementById("writings-content");n&&"undefined"!=typeof SANYAL_DATA&&(n.innerHTML=`\n        <div class="writings-list">\n            ${SANYAL_DATA.writings.map(n=>`\n                <div class="writing-card">\n                    <div class="writing-header">\n                        <h3 class="writing-title">📖 ${n.title}</h3>\n                        <span class="writing-year">${n.year}</span>\n                    </div>\n                    <div class="writing-sig">Category: ${n.type} • <em>${n.significance}</em></div>\n                    <p class="writing-desc">${n.description}</p>\n                    <div class="writing-excerpt">\n                        💬 <strong>Key Excerpt:</strong> "${n.excerpt}"\n                    </div>\n                </div>\n            `).join("")}\n        </div>\n    `)}function renderQuotes(){const n=document.getElementById("quotes-content");n&&"undefined"!=typeof SANYAL_DATA&&(n.innerHTML=`\n        <div class="quotes-grid">\n            ${SANYAL_DATA.quotes.map(n=>`\n                <div class="quote-card">\n                    <div class="quote-text">"${n.quote}"</div>\n                    <div>\n                        <p class="quote-author">— ${n.speaker}</p>\n                        <div class="quote-context">${n.context}</div>\n                    </div>\n                </div>\n            `).join("")}\n        </div>\n    `)}function renderGallery(){const n=document.getElementById("gallery-grid");n&&"undefined"!=typeof SANYAL_DATA&&(n.innerHTML=SANYAL_DATA.gallery.map((n,e)=>`\n        <div class="gallery-item" data-index="${e}">\n            <img src="${n.image}" alt="${n.title}" loading="lazy" />\n            <div class="gallery-overlay">\n                <span class="gallery-cat">${n.category}</span>\n                <h4 class="gallery-title">${n.title}</h4>\n            </div>\n        </div>\n    `).join(""))}function initLightbox(){const n=document.getElementById("sn-lightbox"),e=document.getElementById("lightbox-img"),t=document.getElementById("lightbox-caption"),i=document.getElementById("lightbox-close");if(!n||"undefined"==typeof SANYAL_DATA)return;document.addEventListener("click",i=>{const a=i.target.closest(".gallery-item");if(a){const i=a.dataset.index,s=SANYAL_DATA.gallery[i];s&&(e.src=s.image,e.alt=s.title,t.textContent=`${s.title} — ${s.caption}`,n.classList.add("active"))}});const a=()=>{n.classList.remove("active")};i&&i.addEventListener("click",a),n.addEventListener("click",e=>{e.target===n&&a()}),document.addEventListener("keydown",e=>{"Escape"===e.key&&n.classList.contains("active")&&a()})}function renderReferences(){const n=document.getElementById("references-content");n&&"undefined"!=typeof SANYAL_DATA&&(n.innerHTML=`\n        <div style="overflow-x: auto;">\n            <table class="references-table">\n                <thead>\n                    <tr>\n                        <th>Document / Source</th>\n                        <th>Author / Origin</th>\n                        <th>Year</th>\n                        <th>Type</th>\n                        <th>Historical Significance</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    ${SANYAL_DATA.references.map(n=>`\n                        <tr>\n                            <td style="font-weight: 700; color: var(--sn-text-main);">${n.source}</td>\n                            <td>${n.author}</td>\n                            <td>${n.year}</td>\n                            <td><span style="color: var(--sn-saffron); font-weight: 600;">${n.type}</span></td>\n                            <td>${n.notes}</td>\n                        </tr>\n                    `).join("")}\n                </tbody>\n            </table>\n        </div>\n    `)}document.addEventListener("DOMContentLoaded",()=>{initTabNavigation(),renderBiography(),renderTimeline(),renderHRAHistory(),renderWritings(),renderQuotes(),renderGallery(),renderReferences(),initLightbox(),initQuiz(),initAudioGuide()});let currentQuizIdx=0,quizScore=0;function initQuiz(){document.getElementById("quiz-content")&&"undefined"!=typeof SANYAL_DATA&&renderQuizQuestion()}function renderQuizQuestion(){const n=document.getElementById("quiz-content"),e=SANYAL_DATA.quizQuestions;if(currentQuizIdx>=e.length)return n.innerHTML=`\n            <div style="text-align: center;">\n                <h3 style="font-family: var(--sn-font-heading); font-size: 2rem; color: var(--sn-saffron);">🎉 Quiz Completed!</h3>\n                <p style="font-size: 1.2rem; margin: 1rem 0;">You scored <strong>${quizScore}</strong> out of <strong>${e.length}</strong>!</p>\n                <button id="btn-restart-quiz" class="btn-next-quiz">Try Again 🔄</button>\n            </div>\n        `,void document.getElementById("btn-restart-quiz").addEventListener("click",()=>{currentQuizIdx=0,quizScore=0,renderQuizQuestion()});const t=e[currentQuizIdx];n.innerHTML=`\n        <div style="font-size: 0.9rem; color: var(--sn-text-muted); margin-bottom: 0.5rem;">Question ${currentQuizIdx+1} of ${e.length}</div>\n        <h3 class="quiz-question-title">${t.question}</h3>\n        <div class="quiz-options">\n            ${t.options.map((n,e)=>`\n                <button class="quiz-opt-btn" data-opt="${e}">${n}</button>\n            `).join("")}\n        </div>\n        <div id="quiz-feedback" class="quiz-feedback"></div>\n        <button id="btn-next-q" class="btn-next-quiz" style="display: none;">Next Question ➔</button>\n    `;const i=n.querySelectorAll(".quiz-opt-btn"),a=document.getElementById("quiz-feedback"),s=document.getElementById("btn-next-q");i.forEach(n=>{n.addEventListener("click",()=>{i.forEach(n=>n.disabled=!0);parseInt(n.dataset.opt)===t.correct?(n.classList.add("correct"),quizScore++,a.className="quiz-feedback show",a.style.background="rgba(46, 204, 113, 0.15)",a.style.color="#2ecc71",a.style.border="1px solid #2ecc71",a.innerHTML=`<strong>Correct!</strong> ${t.explanation}`):(n.classList.add("wrong"),i[t.correct].classList.add("correct"),a.className="quiz-feedback show",a.style.background="rgba(231, 76, 60, 0.15)",a.style.color="#e74c3c",a.style.border="1px solid #e74c3c",a.innerHTML=`<strong>Incorrect.</strong> ${t.explanation}`),s.style.display="inline-block"})}),s.addEventListener("click",()=>{currentQuizIdx++,renderQuizQuestion()})}